definition:
def(MINOR_SQRT, "02", "제곱근의 표현", SEC.제곱근, "기본", (rng) =>
    attempt(60, () => {
      const n = pick(rng, SQUAREFREE);
      const branch = intBetween(rng, 0, 2);
      const ask =
        branch === 0
          ? `$${n}$ 의 양의 제곱근`
          : branch === 1
            ? `$${n}$ 의 음의 제곱근`
            : `제곱근 $${n}$`;
      const body = branch === 1 ? `-\\sqrt{${n}}` : `\\sqrt{${n}}`;
      const why =
        branch === 2
          ? `「제곱근 $${n}$」 은 $${n}$ 의 양의 제곱근을 뜻하므로 $\\sqrt{${n}}$ 이다.`
          : `$${n}$ 의 제곱근은 $\\pm\\sqrt{${n}}$ 이므로 ${branch === 0 ? "양" : "음"}의 제곱근은 $${body}$ 이다.`;
      return {
        content: `다음을 근호를 사용하여 나타내시오.\n${ask}`,
        answer: `$${body}$`,
        solution: why,
        facts: { n, branch },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_SQRT,
    "03",
    "근호를 사용하지 않고 나타내기",
    SEC.제곱근,
    "기본",
    (rng) =>
      attempt(60, () => {
        const branch = intBetween(rng, 0, 3);
        if (branch === 3) {
          const p = intBetween(rng, 2, 9);
          const q = intBetween(rng, 2, 9);
          if (gcd(p, q) !== 1 || p === q) return null;
          return {
            content: `다음을 근호를 사용하지 않고 나타내시오.\n$\\sqrt{\\dfrac{${p * p}}{${q * q}}}$`,
            answer: `$\\dfrac{${p}}{${q}}$`,
            solution: `$\\dfrac{${p * p}}{${q * q}}=\\left(\\dfrac{${p}}{${q}}\\right)^2$ 이고 $\\dfrac{${p}}{${q}}>0$ 이다.\n따라서 $\\sqrt{\\dfrac{${p * p}}{${q * q}}}=\\dfrac{${p}}{${q}}$ 이다.`,
            facts: { branch, p, q, k: 0, value: 0 },
            figureSpec: null,
          };
        }
        const k = intBetween(rng, 2, 15);
        const expr =
          branch === 0
            ? `\\sqrt{${k * k}}`
            : branch === 1
              ? `-\\sqrt{${k * k}}`
              : `\\sqrt{(-${k})^2}`;
        const value = branch === 1 ? -k : k;
        const why =
          branch === 2
            ? `$(-${k})^2=${k * k}$ 이고 $${k}>0$ 이므로 $\\sqrt{(-${k})^2}=${k}$ 이다.`
            : `$${k}^2=${k * k}$ 이고 $${k}>0$ 이므로 $${expr}=${value}$ 이다.`;
        return {
          content: `다음을 근호를 사용하지 않고 나타내시오.\n$${expr}$`,
          answer: `$${value}$`,
          solution: why,
          facts: { branch, k, value, p: 0, q: 0 },
          figureSpec: null,
        };
      }),
  )

def(MINOR_SQRT, "04", "제곱근 구하기", SEC.제곱근, "응용", (rng) =>
    attempt(60, () => {
      const k = intBetween(rng, 2, 7);
      const a = k * k * k * k;
      const branch = intBetween(rng, 0, 1);
      if (branch === 0) {
        return {
          content: `$\\sqrt{${a}}$ 의 제곱근을 구하시오.`,
          answer: `$\\pm ${k}$`,
          solution: `$\\sqrt{${a}}=${k * k}$ 이고 $${k * k}$ 의 제곱근은 $\\pm ${k}$ 이다.`,
          facts: { a, k, branch },
          figureSpec: null,
        };
      }
      return {
        content: `$\\sqrt{${a}}$ 의 양의 제곱근을 구하시오.`,
        answer: `$${k}$`,
        solution: `$\\sqrt{${a}}=${k * k}$ 이고 $${k * k}$ 의 양의 제곱근은 $${k}$ 이다.`,
        facts: { a, k, branch },
        figureSpec: null,
      };
    }),
  )

def(MINOR_SQRT, "05", "제곱근과 도형", SEC.제곱근, "응용", (rng) =>
    attempt(80, () => {
      const branch = intBetween(rng, 0, 1);
      if (branch === 0) {
        const m = intBetween(rng, 2, 6);
        const s = pick(rng, SMALL_SF);
        const area = m * m * s;
        return {
          content: `넓이가 $${area}\\,\\mathrm{cm}^2$ 인 정사각형의 한 변의 길이를 구하시오.`,
          answer: `$${sqrtTerm(m, s)}\\,\\mathrm{cm}$`,
          solution: `한 변의 길이를 $x\\,\\mathrm{cm}$ 라 하면 $x>0$ 이고 $x^2=${area}$ 이다.\n따라서 $x=\\sqrt{${area}}=${sqrtTerm(m, s)}$ 이다.`,
          facts: { branch, area, out: m, inner: s, p: 0, q: 0 },
          figureSpec: null,
        };
      }
      const p = intBetween(rng, 2, 9);
      const q = intBetween(rng, 2, 9);
      if (p === q) return null;
      const d = p * p + q * q;
      const s = simplifySqrt(d);
      if (s.inner === 1) return null;
      return {
        content: `가로의 길이가 $${p}\\,\\mathrm{cm}$, 세로의 길이가 $${q}\\,\\mathrm{cm}$ 인 직사각형의 대각선의 길이를 구하시오.`,
        answer: `$${sqrtTerm(s.out, s.inner)}\\,\\mathrm{cm}$`,
        solution: `대각선의 길이를 $x\\,\\mathrm{cm}$ 라 하면 피타고라스 정리에 의하여 $x^2=${p}^2+${q}^2=${d}$ 이다.\n$x>0$ 이므로 $x=${chain(`\\sqrt{${d}}`, sqrtTerm(s.out, s.inner))}$ 이다.`,
        facts: { branch, area: 0, out: s.out, inner: s.inner, p, q },
        figureSpec: null,
      };
    }),
  )

def(MINOR_SQRT, "08", "의 성질", SEC.제곱근, "응용", (rng) =>
    attempt(80, () => {
      const p = intBetween(rng, 1, 5);
      const q = intBetween(rng, 1, 5);
      if (p === q) return null;
      const sign = pick(rng, [1, -1] as const);
      const coef = sign > 0 ? p - q : q - p;
      const pa = coefLetter(p, "a");
      const qa = coefLetter(q, "a");
      const t1 = p === 1 ? "\\sqrt{a^2}" : `\\sqrt{(${pa})^2}`;
      const t2 = `\\sqrt{(-${qa})^2}`;
      const cond = sign > 0 ? "a>0" : "a<0";
      const v1 = sign > 0 ? pa : `-${pa}`;
      const v2 = sign > 0 ? qa : `-${qa}`;
      return {
        content: `$${cond}$ 일 때, 다음 식을 간단히 하시오.\n$${t1}-${t2}$`,
        answer: `$${coefLetter(coef, "a")}$`,
        solution: `$${cond}$ 이므로 $${t1}=|${pa}|=${v1}$, $${t2}=|-${qa}|=${v2}$ 이다.\n따라서 주어진 식은 $${paren(v1)}-${paren(v2)}=${coefLetter(coef, "a")}$ 이다.`,
        facts: { p, q, sign, coef },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_SQRT,
    "09",
    "의 꼴을 포함한 식을 간단히 하기",
    SEC.제곱근,
    "응용",
    (rng) =>
      attempt(80, () => {
        const a = intBetween(rng, 1, 7);
        const b = a + intBetween(rng, 2, 8);
        const branch = intBetween(rng, 0, 1);
        const t1 = `\\sqrt{(x-${a})^2}`;
        const t2 = `\\sqrt{(x-${b})^2}`;
        const head = `$${a}<x<${b}$ 이므로 $x-${a}>0$, $x-${b}<0$ 이다.\n따라서 $${t1}=x-${a}$, $${t2}=${b}-x$ 이므로 주어진 식은`;
        if (branch === 0) {
          return {
            content: `$${a}<x<${b}$ 일 때, 다음 식을 간단히 하시오.\n$${t1}+${t2}$`,
            answer: `$${b - a}$`,
            solution: `${head} $(x-${a})+(${b}-x)=${b - a}$ 이다.`,
            facts: { a, b, branch },
            figureSpec: null,
          };
        }
        return {
          content: `$${a}<x<${b}$ 일 때, 다음 식을 간단히 하시오.\n$${t1}-${t2}$`,
          answer: `$2x-${a + b}$`,
          solution: `${head} $(x-${a})-(${b}-x)=2x-${a + b}$ 이다.`,
          facts: { a, b, branch },
          figureSpec: null,
        };
      }),
  )

def(
    MINOR_SQRT,
    "10",
    "의 꼴을 포함한 식을 간단히 하기",
    SEC.제곱근,
    "심화하",
    (rng) =>
      attempt(120, () => {
        const p = intBetween(rng, 1, 5);
        const q = intBetween(rng, 1, 5);
        const r = intBetween(rng, 1, 5);
        if (p === r) return null;
        const sa = pick(rng, [1, -1] as const);
        const sb = pick(rng, [1, -1] as const);
        const ca = sa * (p - r);
        const cb = sb * q;
        if (ca === 0 || cb === 0) return null;
        const pa = coefLetter(p, "a");
        const qb = coefLetter(q, "b");
        const ra = coefLetter(r, "a");
        const t1 = p === 1 ? "\\sqrt{a^2}" : `\\sqrt{(${pa})^2}`;
        const t2 = q === 1 ? "\\sqrt{b^2}" : `\\sqrt{(${qb})^2}`;
        const t3 = `\\sqrt{(-${ra})^2}`;
        const v1 = sa > 0 ? pa : `-${pa}`;
        const v2 = sb > 0 ? qb : `-${qb}`;
        const v3 = sa > 0 ? ra : `-${ra}`;
        const cond = `$a${sa > 0 ? ">" : "<"}0$, $b${sb > 0 ? ">" : "<"}0$`;
        return {
          content: `${cond} 일 때, 다음 식을 간단히 하시오.\n$${t1}+${t2}-${t3}$`,
          answer: `$${linearAB(ca, cb)}$`,
          solution: `${cond} 이므로 $${t1}=${v1}$, $${t2}=${v2}$, $${t3}=${v3}$ 이다.\n따라서 주어진 식은 $${paren(v1)}+${paren(v2)}-${paren(v3)}=${linearAB(ca, cb)}$ 이다.`,
          facts: { p, q, r, sa, sb, ca, cb },
          figureSpec: null,
        };
      }),
  )

def(
    MINOR_SQRT,
    "13",
    "가 자연수가 되도록 하는 자연수 의 값 구하기",
    SEC.제곱근,
    "응용",
    (rng) =>
      attempt(80, () => {
        const a = intBetween(rng, 20, 200);
        if (isPerfectSquare(a)) return null;
        const k = Math.ceil(Math.sqrt(a));
        const x = k * k - a;
        return {
          content: `$\\sqrt{${a}+x}$ 가 자연수가 되도록 하는 가장 작은 자연수 $x$ 의 값을 구하시오.`,
          answer: `$${x}$`,
          solution: `$${a}$ 보다 큰 자연수의 제곱 중 가장 작은 것은 $${k}^2=${k * k}$ 이다.\n따라서 $${a}+x=${k * k}$ 에서 $x=${x}$ 이다.`,
          facts: { a, k, x },
          figureSpec: null,
        };
      }),
  )

def(
    MINOR_SQRT,
    "14",
    "가 정수 또는 자연수가 되도록 하는 자연수 의 값 구하기",
    SEC.제곱근,
    "심화하",
    (rng) =>
      attempt(60, () => {
        const a = intBetween(rng, 20, 200);
        const k = Math.floor(Math.sqrt(a - 1));
        const count = k + 1;
        return {
          content: `$\\sqrt{${a}-x}$ 가 정수가 되도록 하는 자연수 $x$ 의 개수를 구하시오.`,
          answer: `$${count}$`,
          solution: `$x$ 가 자연수이므로 $${a}-x$ 는 $0$ 이상 $${a - 1}$ 이하의 정수이다.\n이 중 정수의 제곱인 것은 $0^2,\\ 1^2,\\ \\ldots,\\ ${k}^2$ 의 $${count}$ 개이므로 $x$ 의 개수도 $${count}$ 이다.`,
          facts: { a, k, count },
          figureSpec: null,
        };
      }),
  )

def(MINOR_IRR, "02", "무리수의 이해", SEC.무리수, "응용", (rng) =>
    attempt(60, () => {
      const n = intBetween(rng, 20, 60);
      const squares = Math.floor(Math.sqrt(n));
      const count = n - squares;
      return {
        content: `$1$ 부터 $${n}$ 까지의 자연수 $k$ 중에서 $\\sqrt{k}$ 가 무리수인 것은 모두 몇 개인지 구하시오.`,
        answer: `$${count}$`,
        solution: `$\\sqrt{k}$ 가 유리수이려면 $k$ 가 어떤 자연수의 제곱이어야 한다.\n$1$ 부터 $${n}$ 까지 그런 $k$ 는 $1^2,\\ 2^2,\\ \\ldots,\\ ${squares}^2$ 의 $${squares}$ 개이므로 무리수인 것은 $${n}-${squares}=${count}$ 개이다.`,
        facts: { n, squares, count },
        figureSpec: null,
      };
    }),
  )

def(MINOR_IRR, "03", "실수의 이해", SEC.무리수, "응용", (rng) =>
    attempt(60, () => {
      const items = numberListItems(rng, 5);
      const irr = items.filter((t) => t.irrational).length;
      const rat = items.length - irr;
      if (irr === 0 || rat === 0) return null;
      const value = rat - irr;
      return {
        content: `다음 수 중 유리수의 개수를 $a$, 무리수의 개수를 $b$ 라 할 때, $a-b$ 의 값을 구하시오.\n${items.map((t) => `$${t.latex}$`).join(", ")}`,
        answer: `$${value}$`,
        solution: `유리수와 무리수를 통틀어 실수라 한다. 주어진 수는 유리수 $${rat}$ 개, 무리수 $${irr}$ 개이다.\n따라서 $a-b=${rat}-${irr}=${value}$ 이다.`,
        facts: { rat, irr, value },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_IRR,
    "04",
    "무리수를 수직선 위에 나타내기",
    SEC.무리수,
    "응용",
    (rng) =>
      attempt(120, () => {
        const c = intBetween(rng, -5, 5);
        const p = intBetween(rng, 1, 6);
        const q = intBetween(rng, 1, 6);
        if (p === q) return null;
        const d = p * p + q * q;
        const s = simplifySqrt(d);
        if (s.inner === 1) return null;
        const branch = intBetween(rng, 0, 1);
        const dir = branch === 0 ? "오른쪽" : "왼쪽";
        const coef = branch === 0 ? s.out : -s.out;
        return {
          content: `수직선 위에서 좌표가 $${c}$ 인 점 A를 한 꼭짓점으로 하고 가로의 길이가 $${p}$, 세로의 길이가 $${q}$ 인 직사각형이 있다. 점 A를 중심으로 하고 이 직사각형의 대각선의 길이를 반지름으로 하는 원을 그릴 때, 이 원이 수직선과 만나는 두 점 중 ${dir}에 있는 점 P에 대응하는 수를 구하시오.`,
          answer: `$${constPlusSurd(c, coef, s.inner)}$`,
          solution: `직사각형의 대각선의 길이는 $${chain(`\\sqrt{${p}^2+${q}^2}`, `\\sqrt{${d}}`, sqrtTerm(s.out, s.inner))}$ 이다.\n점 P는 점 A에서 ${dir}으로 이 길이만큼 떨어진 점이므로 대응하는 수는 $${constPlusSurd(c, coef, s.inner)}$ 이다.`,
          facts: { c, p, q, out: s.out, inner: s.inner, branch },
          figureSpec: null,
        };
      }),
  )

def(MINOR_IRR, "05", "실수와 수직선", SEC.무리수, "기본", (rng) =>
    attempt(80, () => {
      const n = pick(rng, SQUAREFREE);
      if (n < 5) return null;
      const k = Math.floor(Math.sqrt(n));
      return {
        content: `$\\sqrt{${n}}$ 에 대응하는 점은 수직선 위에서 연속하는 두 정수 사이에 있다. 그 두 정수를 구하시오.`,
        answer: `$${k}$ ${waGwa(k)} $${k + 1}$`,
        solution: `$${k}^2=${k * k}$, $(${k + 1})^2=${(k + 1) * (k + 1)}$ 이고 $${k * k}<${n}<${(k + 1) * (k + 1)}$ 이므로 $${k}<\\sqrt{${n}}<${k + 1}$ 이다.\n따라서 두 정수는 $${k}$ ${waGwa(k)} $${k + 1}$ 이다.`,
        facts: { n, k },
        figureSpec: null,
      };
    }),
  )

def(MINOR_IRR, "08", "세 실수의 대소 관계", SEC.무리수, "심화하", (rng) =>
    attempt(200, () => {
      const parts = [0, 1, 2].map(() => {
        const useRad = intBetween(rng, 0, 3) > 0;
        const k = intBetween(rng, 0, 4);
        const r = useRad ? pick(rng, SQUAREFREE) : 0;
        return { k, r };
      });
      // 근호가 하나뿐이면 「세 실수의 대소」가 아니라 정수 비교가 된다.
      if (parts.filter((t) => t.r !== 0).length < 2) return null;
      const items = parts.map(({ k, r }) => ({
        latex:
          r === 0 ? `${k}` : k === 0 ? `\\sqrt{${r}}` : `${k}+\\sqrt{${r}}`,
        value: k + (r === 0 ? 0 : Math.sqrt(r)),
      }));
      if (items.some((t) => t.value === 0)) return null;
      if (new Set(items.map((t) => t.latex)).size !== 3) return null;
      for (let i = 0; i < 3; i += 1) {
        for (let j = i + 1; j < 3; j += 1) {
          if (Math.abs(items[i]!.value - items[j]!.value) < 0.1) return null;
        }
      }
      const desc = [...items].sort((x, y) => y.value - x.value);
      return {
        content: `다음 세 수를 큰 것부터 차례로 나열하시오.\n$${items[0]!.latex}$, $${items[1]!.latex}$, $${items[2]!.latex}$`,
        answer: `$${desc.map((t) => t.latex).join(">")}$`,
        solution: `두 수의 차를 구하여 그 부호를 살피면 대소를 알 수 있다.\n큰 것부터 나열하면 $${desc.map((t) => t.latex).join(">")}$ 이다.`,
        facts: {
          k0: parts[0]!.k,
          r0: parts[0]!.r,
          k1: parts[1]!.k,
          r1: parts[1]!.r,
          k2: parts[2]!.k,
          r2: parts[2]!.r,
        },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_IRR,
    "09",
    "제곱근표를 이용하여 제곱근의 값 구하기",
    SEC.무리수,
    "응용",
    (rng) =>
      attempt(60, () => {
        const a2 = intBetween(rng, 100, 999);
        const v3 = Math.round(Math.sqrt(a2 / 100) * 1000);
        const mult = pick(rng, [10, 100] as const);
        const b = mult === 10 ? a2 : a2 * 100;
        const aStr = (a2 / 100).toFixed(2);
        const vStr = (v3 / 1000).toFixed(3);
        return {
          content: `제곱근표에 $\\sqrt{${aStr}}\\approx${vStr}$으로 나와 있다. 표의 근삿값을 그대로 이용하여 $\\sqrt{${b}}$의 근삿값을 구하시오.`,
          answer: `$${trimNum((v3 / 1000) * mult)}$`,
          solution: `$${b}=${aStr}\\times${mult * mult}$ 이므로 $\\sqrt{${b}}=${mult}\\sqrt{${aStr}}$ 이다.\n표의 근삿값을 그대로 이용하면 $\\sqrt{${b}}\\approx${mult}\\times${vStr}=${trimNum((v3 / 1000) * mult)}$ 이다.`,
          facts: { a2, v3, mult },
          figureSpec: null,
        };
      }),
  )

def(MINOR_IRR, "10", "두 실수 사이의 수", SEC.무리수, "응용", (rng) =>
    attempt(120, () => {
      const a = pick(rng, SQUAREFREE);
      const b = pick(rng, SQUAREFREE);
      if (b <= a) return null;
      const ka = Math.floor(Math.sqrt(a));
      const kb = Math.floor(Math.sqrt(b));
      const count = kb - ka;
      if (count === 0) return null;
      return {
        content: `$\\sqrt{${a}}$ ${waGwa(a)} $\\sqrt{${b}}$ 사이에 있는 자연수의 개수를 구하시오.`,
        answer: `$${count}$`,
        solution: `$${ka}<\\sqrt{${a}}<${ka + 1}$, $${kb}<\\sqrt{${b}}<${kb + 1}$ 이다.\n따라서 두 수 사이의 자연수는 $${ka + 1}$ 부터 $${kb}$ 까지의 $${count}$ 개이다.`,
        facts: { a, b, count },
        figureSpec: null,
      };
    }),
  )

def(MINOR_CALC, "02", "제곱근의 나눗셈", SEC.근호계산, "기본", (rng) =>
    attempt(200, () => {
      // 답(정리된 꼴)을 먼저 정하고 나눠지는 수를 만든다 — 역산하지 않는다.
      const inner = pick(rng, SMALL_SF);
      const n = pick(rng, SMALL_SF);
      if (inner === n) return null;
      const m = inner * n;
      if (!isSquareFree(m)) return null;
      const out = intBetween(rng, 1, 5);
      const q = intBetween(rng, 1, 4);
      const p = out * q;
      if (p === 1 && q === 1 && out === 1) return null;
      return {
        content: `다음 식을 계산하시오.\n$${sqrtTerm(p, m)}\\div${sqrtTerm(q, n)}$`,
        answer: `$${sqrtTerm(out, inner)}$`,
        solution: `근호 안끼리 나누면 $\\sqrt{\\dfrac{${m}}{${n}}}=\\sqrt{${inner}}$ 이다.\n계수끼리 나누면 $${p}\\div${q}=${out}$ 이므로 주어진 식은 $${sqrtTerm(out, inner)}$ 이다.`,
        facts: { p, m, q, n, out, inner },
        figureSpec: null,
      };
    }),
  )

def(MINOR_CALC, "03", "를 이용한 식의 변형", SEC.근호계산, "기본", (rng) =>
    attempt(60, () => {
      const m = intBetween(rng, 2, 7);
      const s = pick(rng, SMALL_SF);
      const n = m * m * s;
      return {
        content: `$\\sqrt{${n}}$ ${eulReul(n)} $a\\sqrt{b}$ 꼴로 나타내시오. (단, $a$, $b$ 는 자연수이고 $b$ 는 가장 작은 수)`,
        answer: `$${sqrtTerm(m, s)}$`,
        solution: `$${n}=${m}^2\\times${s}$ 이므로 $\\sqrt{${n}}=\\sqrt{${m}^2\\times${s}}=${sqrtTerm(m, s)}$ 이다.`,
        facts: { n, out: m, inner: s },
        figureSpec: null,
      };
    }),
  )

def(MINOR_CALC, "04", "를 이용한 식의 변형", SEC.근호계산, "기본", (rng) =>
    attempt(60, () => {
      const k = intBetween(rng, 2, 6);
      const m = pick(rng, SMALL_SF);
      const n = k * k * m;
      return {
        content: `$${sqrtTerm(k, m)}$ ${eulReul(m)} $\\sqrt{a}$ 꼴로 나타내시오. (단, $a$ 는 자연수)`,
        answer: `$\\sqrt{${n}}$`,
        solution: `$${k}=\\sqrt{${k * k}}$ 이므로 $${sqrtTerm(k, m)}=\\sqrt{${k * k}}\\times\\sqrt{${m}}=\\sqrt{${n}}$ 이다.`,
        facts: { k, m, n },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_CALC,
    "05",
    "제곱근표에 없는 수의 제곱근의 값 구하기",
    SEC.근호계산,
    "응용",
    (rng) =>
      attempt(60, () => {
        const a = pick(rng, [2, 3, 5, 6, 7, 10] as const);
        const v3 = Math.round(Math.sqrt(a) * 1000);
        const branch = intBetween(rng, 0, 1);
        const mult = branch === 0 ? intBetween(rng, 2, 5) : 10;
        const b = mult * mult * a;
        const vStr = (v3 / 1000).toFixed(3);
        return {
          content: `$\\sqrt{${a}}=${vStr}$ 일 때, $\\sqrt{${b}}$ 의 값을 구하시오.`,
          answer: `$${trimNum((v3 / 1000) * mult)}$`,
          solution: `$${b}=${mult}^2\\times${a}$ 이므로 $\\sqrt{${b}}=${mult}\\sqrt{${a}}$ 이다.\n따라서 $\\sqrt{${b}}=${mult}\\times${vStr}=${trimNum((v3 / 1000) * mult)}$ 이다.`,
          facts: { a, v3, mult, b },
          figureSpec: null,
        };
      }),
  )

def(
    MINOR_CALC,
    "08",
    "제곱근의 곱셈과 나눗셈의 혼합 계산",
    SEC.근호계산,
    "응용",
    (rng) =>
      attempt(300, () => {
        const a = pick(rng, SMALL_SF);
        const divisors = SMALL_SF.filter((d) => d > 1 && a % d === 0);
        if (divisors.length === 0) return null;
        const c = pick(rng, divisors);
        const w = a / c;
        const b = pick(rng, SMALL_SF);
        const r = intBetween(rng, 1, 3);
        const p = intBetween(rng, 1, 6);
        const q = intBetween(rng, 1, 6);
        if ((p * q) % r !== 0) return null;
        const s = simplifySqrt(w * b);
        if (s.inner === 1) return null;
        const coef = (p * q) / r;
        const out = coef * s.out;
        return {
          content: `다음 식을 계산하시오.\n$${sqrtTerm(p, a)}\\times${sqrtTerm(q, b)}\\div${sqrtTerm(r, c)}$`,
          answer: `$${sqrtTerm(out, s.inner)}$`,
          solution: `근호 안끼리 계산하면 $${chain(`\\sqrt{\\dfrac{${a}\\times${b}}{${c}}}`, `\\sqrt{${w * b}}`, sqrtTerm(s.out, s.inner))}$ 이다.\n계수끼리 계산하면 $${p}\\times${q}\\div${r}=${coef}$ 이므로 주어진 식은 $${sqrtTerm(out, s.inner)}$ 이다.`,
          facts: { p, a, q, b, r, c, out, inner: s.inner },
          figureSpec: null,
        };
      }),
  )

def(
    MINOR_CALC,
    "09",
    "제곱근의 곱셈과 나눗셈의 도형에의 활용",
    SEC.근호계산,
    "응용",
    (rng) =>
      attempt(120, () => {
        const p = intBetween(rng, 1, 5);
        const q = intBetween(rng, 1, 5);
        const a = pick(rng, MULT_SF);
        const b = pick(rng, MULT_SF);
        if (a === b) return null;
        const branch = intBetween(rng, 0, 1);
        if (branch === 1 && (p * q) % 2 !== 0) return null;
        const s = simplifySqrt(a * b);
        const coef = branch === 0 ? p * q : (p * q) / 2;
        const out = coef * s.out;
        const w = sqrtTerm(p, a);
        const h = sqrtTerm(q, b);
        const fin = `${sqrtTerm(out, s.inner)}\\,\\mathrm{cm}^2`;
        if (branch === 0) {
          return {
            content: `가로의 길이가 $${w}\\,\\mathrm{cm}$, 세로의 길이가 $${h}\\,\\mathrm{cm}$ 인 직사각형의 넓이를 구하시오.`,
            answer: `$${fin}$`,
            solution: `(직사각형의 넓이)$=${chain(`${w}\\times${h}`, sqrtTerm(coef, a * b), sqrtTerm(out, s.inner))}$ 이므로 넓이는 $${fin}$ 이다.`,
            facts: { p, a, q, b, out, inner: s.inner, branch },
            figureSpec: null,
          };
        }
        return {
          content: `밑변의 길이가 $${w}\\,\\mathrm{cm}$, 높이가 $${h}\\,\\mathrm{cm}$ 인 삼각형의 넓이를 구하시오.`,
          answer: `$${fin}$`,
          solution: `(삼각형의 넓이)$=${chain(`\\dfrac{1}{2}\\times${w}\\times${h}`, sqrtTerm(coef, a * b), sqrtTerm(out, s.inner))}$ 이므로 넓이는 $${fin}$ 이다.`,
          facts: { p, a, q, b, out, inner: s.inner, branch },
          figureSpec: null,
        };
      }),
  )

def(MINOR_CALC, "10", "제곱근의 덧셈과 뺄셈", SEC.근호계산, "기본", (rng) =>
    attempt(120, () => {
      const m = pick(rng, SQUAREFREE);
      const n = pick(rng, SQUAREFREE);
      if (m === n) return null;
      const p = intBetween(rng, 1, 7);
      const q = intBetween(rng, 1, 7);
      const r = intBetween(rng, 1, 7);
      if (p === r) return null;
      const c1 = p - r;
      const ans = sumSurds([
        { coef: c1, inner: m },
        { coef: q, inner: n },
      ]);
      return {
        content: `다음 식을 계산하시오.\n$${sqrtTerm(p, m)}+${sqrtTerm(q, n)}-${sqrtTerm(r, m)}$`,
        answer: `$${ans}$`,
        solution: `$\\sqrt{${m}}$ 끼리 모으면 $(${p}-${r})\\sqrt{${m}}=${sqrtTerm(c1, m)}$ 이다.\n따라서 주어진 식은 $${ans}$ 이다.`,
        facts: { p, q, r, m, n, c1, c2: q },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_CALC,
    "13",
    "제곱근의 덧셈과 뺄셈의 수직선에의 활용",
    SEC.근호계산,
    "응용",
    (rng) =>
      attempt(120, () => {
        const c = intBetween(rng, -4, 6);
        const s = pick(rng, [2, 3, 5, 6, 7] as const);
        const a = intBetween(rng, 1, 5);
        const b = intBetween(rng, 1, 5);
        if (a === b) return null;
        const A = a * a * s;
        const B = b * b * s;
        if (Math.max(A, B) > 200) return null;
        const k = a - b;
        return {
          content: `수직선 위에서 좌표가 $${c}$ 인 점에서 오른쪽으로 $\\sqrt{${A}}$ 만큼 이동한 후, 다시 왼쪽으로 $\\sqrt{${B}}$ 만큼 이동한 점에 대응하는 수를 구하시오.`,
          answer: `$${constPlusSurd(c, k, s)}$`,
          solution: `$${chain(`\\sqrt{${A}}`, sqrtTerm(a, s))}$, $${chain(`\\sqrt{${B}}`, sqrtTerm(b, s))}$ 이다.\n따라서 대응하는 수는 $${c}+${sqrtTerm(a, s)}-${sqrtTerm(b, s)}=${constPlusSurd(c, k, s)}$ 이다.`,
          facts: { c, A, B, s, k },
          figureSpec: null,
        };
      }),
  )

def(
    MINOR_CALC,
    "14",
    "분배법칙을 이용한 근호를 포함한 식의 계산",
    SEC.근호계산,
    "응용",
    (rng) =>
      attempt(200, () => {
        const a = pick(rng, MULT_SF);
        const b = pick(rng, MULT_SF);
        const c = pick(rng, MULT_SF);
        const p = intBetween(rng, 1, 5);
        if (b === c) return null;
        const s1 = simplifySqrt(a * b);
        const s2 = simplifySqrt(a * c);
        if (s1.inner === s2.inner) return null;
        if (s1.inner === 1 || s2.inner === 1) return null;
        const t1 = { coef: s1.out, inner: s1.inner };
        const t2 = { coef: p * s2.out, inner: s2.inner };
        const raw = `\\sqrt{${a * b}}+${sqrtTerm(p, a * c)}`;
        const ans = sumSurds([t1, t2]);
        return {
          content: `다음 식을 계산하시오.\n$\\sqrt{${a}}(\\sqrt{${b}}+${sqrtTerm(p, c)})$`,
          answer: `$${ans}$`,
          solution: `분배법칙에 의하여 $\\sqrt{${a}}\\times\\sqrt{${b}}+\\sqrt{${a}}\\times${sqrtTerm(p, c)}=${raw}$ 이다.\n근호 안을 정리하면 $${ans}$ 이다.`,
          facts: {
            a,
            b,
            c,
            p,
            o1: t1.coef,
            i1: t1.inner,
            o2: t2.coef,
            i2: t2.inner,
          },
          figureSpec: null,
        };
      }),
  )

def(MINOR_CALC, "19", "실수의 대소 관계", SEC.근호계산, "응용", (rng) =>
    attempt(120, () => {
      const p = intBetween(rng, 1, 5);
      const q = intBetween(rng, 1, 5);
      const m = pick(rng, SMALL_SF);
      const n = pick(rng, SMALL_SF);
      const left = p * p * m;
      const right = q * q * n;
      if (left === right) return null;
      if (sqrtTerm(p, m) === sqrtTerm(q, n)) return null;
      const lt = left < right ? 1 : 0;
      const rel = lt === 1 ? "<" : ">";
      const moved = (
        [
          [p, m, left],
          [q, n, right],
        ] as const
      )
        .filter(([c]) => c !== 1)
        .map(([c, r, v]) => `$${sqrtTerm(c, r)}=\\sqrt{${v}}$`);
      return {
        content: `두 수 $${sqrtTerm(p, m)}$ ${waGwa(m)} $${sqrtTerm(q, n)}$ 의 대소를 비교하시오.`,
        answer: `$${sqrtTerm(p, m)}${rel}${sqrtTerm(q, n)}$`,
        // 계수가 $1$ 인 쪽은 넣을 것이 없다 — `$\sqrt{13}=\sqrt{13}$` 을 적지 않는다.
        solution: `${moved.length ? `근호 안으로 넣으면 ${moved.join(", ")} 이다.\n` : ""}$${left}${rel}${right}$ 이므로 $${sqrtTerm(p, m)}${rel}${sqrtTerm(q, n)}$ 이다.`,
        facts: { p, m, q, n, lt },
        figureSpec: null,
      };
    }),
  )

def(
    MINOR_MUL,
    "02",
    "전개식에서 특정한 항의 계수 구하기",
    SEC.곱셈,
    "응용",
    (rng) =>
      // (ax+b)(cx^2+dx+e) 의 x^2 또는 x 의 계수. 전개식을 다 쓰지 않고 필요한 항만 센다.
      attempt<Gen>(80, () => {
        const a = intBetween(rng, 2, 5);
        const b = nonZero(rng, -6, 6);
        const c = intBetween(rng, 1, 4);
        const d = nonZero(rng, -6, 6);
        const e = nonZero(rng, -7, 7);
        const which = pick(rng, [2, 1] as const);
        const coef = which === 2 ? a * d + b * c : a * e + b * d;
        if (coef === 0) return null;
        const src = `${par(lin(a, "x", b))}${par(
          polyTex([
            [c, "x^2"],
            [d, "x"],
            [e, ""],
          ]),
        )}`;
        const body = which === 2 ? "x^2" : "x";
        const left =
          which === 2
            ? `${wp(a, "x")}\\times ${wp(d, "x")}`
            : `${wp(a, "x")}\\times ${wp(e, "")}`;
        const right =
          which === 2
            ? `${wp(b, "")}\\times ${wp(c, "x^2")}`
            : `${wp(b, "")}\\times ${wp(d, "x")}`;
        return {
          content: `${M(src)} 의 전개식에서 ${M(body)} 의 계수를 구하시오.`,
          answer: M(String(coef)),
          solution: `${M(body)} 항은 ${M(left)}, ${M(
            right,
          )} 두 곳에서만 나온다.\n두 항의 계수를 더하면 ${M(
            `${
              which === 2
                ? `${wp(a, "")}\\times${wp(d, "")}`
                : `${wp(a, "")}\\times${wp(e, "")}`
            }+${
              which === 2
                ? `${wp(b, "")}\\times${wp(c, "")}`
                : `${wp(b, "")}\\times${wp(d, "")}`
            }=${coef}`,
          )} 이다.`,
          facts: { a, b, c, d, e, which, coef },
        };
      }),
  )

def(MINOR_MUL, "03", "의 전개", SEC.곱셈, "기본", (rng) =>
    // (a±b)^2 = a^2 ± 2ab + b^2
    attempt<Gen>(80, () => {
      const mode = pick(rng, [0, 1] as const);
      if (mode === 0) {
        const a = intBetween(rng, 2, 6);
        const b = nonZero(rng, -6, 6);
        if (gcd(a, Math.abs(b)) !== 1) return null;
        const src = `${par(lin2(a, "x", b, "y"))}^2`;
        const out = polyTex([
          [a * a, "x^2"],
          [2 * a * b, "xy"],
          [b * b, "y^2"],
        ]);
        return {
          content: `${EXPAND}\n${M(src)}`,
          answer: M(out),
          solution: `${M("(A+B)^2=A^2+2AB+B^2")} 임을 이용한다.\n${M(
            `${src}=${out}`,
          )}`,
          facts: { mode, a, b },
        };
      }
      const a = intBetween(rng, 1, 5);
      const b = nonZero(rng, -9, 9);
      if (gcd(a, Math.abs(b)) !== 1) return null;
      const src = `${par(lin(a, "x", b))}^2`;
      const out = polyTex([
        [a * a, "x^2"],
        [2 * a * b, "x"],
        [b * b, ""],
      ]);
      return {
        content: `${EXPAND}\n${M(src)}`,
        answer: M(out),
        solution: `${M("(A+B)^2=A^2+2AB+B^2")} 임을 이용한다.\n${M(`${src}=${out}`)}`,
        facts: { mode, a, b },
      };
    }),
  )

def(MINOR_MUL, "04", "의 전개", SEC.곱셈, "기본", (rng) =>
    // (a+b)(a-b) = a^2-b^2. 세 번째 모드는 순서를 뒤집어 부호를 헷갈리게 한다.
    attempt<Gen>(80, () => {
      const mode = pick(rng, [0, 1, 2] as const);
      const a = intBetween(rng, 1, 7);
      const b = intBetween(rng, 1, 9);
      if (gcd(a, b) !== 1) return null;
      if (mode === 0) {
        const src = `${par(lin2(a, "x", b, "y"))}${par(lin2(a, "x", -b, "y"))}`;
        const out = polyTex([
          [a * a, "x^2"],
          [-b * b, "y^2"],
        ]);
        return {
          content: `${EXPAND}\n${M(src)}`,
          answer: M(out),
          solution: `${M("(A+B)(A-B)=A^2-B^2")} 임을 이용한다.\n${M(`${src}=${out}`)}`,
          facts: { mode, a, b },
        };
      }
      if (mode === 1) {
        const src = `${par(lin(a, "x", b))}${par(lin(a, "x", -b))}`;
        const out = polyTex([
          [a * a, "x^2"],
          [-b * b, ""],
        ]);
        return {
          content: `${EXPAND}\n${M(src)}`,
          answer: M(out),
          solution: `${M("(A+B)(A-B)=A^2-B^2")} 임을 이용한다.\n${M(`${src}=${out}`)}`,
          facts: { mode, a, b },
        };
      }
      const src = `${par(lin2(-a, "x", b, "y"))}${par(lin2(a, "x", b, "y"))}`;
      const out = polyTex([
        [b * b, "y^2"],
        [-a * a, "x^2"],
      ]);
      return {
        content: `${EXPAND}\n${M(src)}`,
        answer: M(out),
        solution: `앞의 식을 ${M(
          `${lin2(b, "y", -a, "x")}`,
        )} 로 보면 두 식은 합과 차의 꼴이다.\n${M(`${src}=${out}`)}`,
        facts: { mode, a, b },
      };
    }),
  )

def(MINOR_MUL, "05", "의 전개", SEC.곱셈, "기본", (rng) =>
    // (x+a)(x+b) = x^2+(a+b)x+ab
    attempt<Gen>(80, () => {
      const mode = pick(rng, [0, 1] as const);
      const a = nonZero(rng, -9, 9);
      const b = nonZero(rng, -9, 9);
      if (a === b) return null;
      if (mode === 0) {
        const src = `${par(lin(1, "x", a))}${par(lin(1, "x", b))}`;
        const out = polyTex([
          [1, "x^2"],
          [a + b, "x"],
          [a * b, ""],
        ]);
        return {
          content: `${EXPAND}\n${M(src)}`,
          answer: M(out),
          solution: `${M(
            "(x+a)(x+b)=x^2+(a+b)x+ab",
          )} 임을 이용한다.\n두 수의 합은 ${M(String(a + b))}, 곱은 ${M(
            String(a * b),
          )} 이므로 ${M(`${src}=${out}`)} 이다.`,
          facts: { mode, a, b },
        };
      }
      const src = `${par(lin2(1, "x", a, "y"))}${par(lin2(1, "x", b, "y"))}`;
      const out = polyTex([
        [1, "x^2"],
        [a + b, "xy"],
        [a * b, "y^2"],
      ]);
      return {
        content: `${EXPAND}\n${M(src)}`,
        answer: M(out),
        solution: `${M("y")} 를 상수처럼 보고 ${M(
          "(x+a)(x+b)=x^2+(a+b)x+ab",
        )} 임을 이용한다.\n${M(`${src}=${out}`)}`,
        facts: { mode, a, b },
      };
    }),
  )

def(MINOR_MUL, "08", "곱셈 공식의 도형에의 활용 ⑴", SEC.곱셈, "응용", (rng) =>
    // 직사각형의 가로를 늘이고 세로를 줄인다 — 그림 없이 발문이 조건을 다 말한다.
    attempt<Gen>(80, () => {
      const a = intBetween(rng, 2, 6);
      const b = intBetween(rng, 2, 6);
      // 가로와 세로가 같은 식이면 「가로 $3x$, 세로 $3x$인 직사각형」 — 정사각형을 직사각형이라
      // 부르는 꼴이다(씨앗 1,000 중 18.3%, 2026-09-27). 09 가 이미 막는 것과 같다.
      // 통과율 92.9% → 76.2%(전수) — 80번이면 던질 확률 $10^{-50}$.
      if (a === b) return null;
      const p = intBetween(rng, 1, 6);
      const q = intBetween(rng, 1, 6);
      if (b * p - a * q === 0) return null;
      const out = polyTex([
        [a * b, "x^2"],
        [b * p - a * q, "x"],
        [-p * q, ""],
      ]);
      const prod = `${par(lin(a, "x", p))}${par(lin(b, "x", -q))}`;
      return {
        content: `가로의 길이가 ${M(`${a}x`)}, 세로의 길이가 ${M(
          `${b}x`,
        )} 인 직사각형이 있다. 가로의 길이는 ${M(
          String(p),
        )} 만큼 늘이고 세로의 길이는 ${M(
          String(q),
        )} 만큼 줄여서 새 직사각형을 만들었을 때, 새 직사각형의 넓이를 구하시오.`,
        answer: M(out),
        solution: `새 직사각형의 가로의 길이는 ${M(
          lin(a, "x", p),
        )}, 세로의 길이는 ${M(lin(b, "x", -q))} 이다.\n${M(`${prod}=${out}`)}`,
        facts: { a, b, p, q },
      };
    }),
  )

def(
    MINOR_MUL,
    "09",
    "곱셈 공식의 도형에의 활용 ⑵",
    SEC.곱셈,
    "심화하",
    (rng) => {
      // 폭이 일정한 길을 가장자리로 몰면 (ax-w)(bx-w) 짜리 직사각형이 남는다.
      const a = intBetween(rng, 2, 6);
      const b = attempt<number>(40, () => {
        const v = intBetween(rng, 2, 6);
        return v === a ? null : v;
      });
      const w = intBetween(rng, 1, 4);
      const out = polyTex([
        [a * b, "x^2"],
        [-(a + b) * w, "x"],
        [w * w, ""],
      ]);
      const prod = `${par(lin(a, "x", -w))}${par(lin(b, "x", -w))}`;
      return {
        content: `가로의 길이가 ${M(`${a}x`)}, 세로의 길이가 ${M(
          `${b}x`,
        )} 인 직사각형 모양의 땅에 폭이 일정하게 ${M(
          String(w),
        )} 인 길을 가로 방향과 세로 방향으로 하나씩 만들었다. 길을 제외한 땅의 넓이를 구하시오.`,
        answer: M(out),
        solution: `두 길을 각각 땅의 가장자리로 옮기면 남는 땅은 가로의 길이가 ${M(
          lin(a, "x", -w),
        )}, 세로의 길이가 ${M(lin(b, "x", -w))} 인 직사각형이다.\n${M(
          `${prod}=${out}`,
        )}`,
        facts: { a, b, w },
      };
    },
  )

def(MINOR_MUL, "10", "공통부분이 있는 식의 전개", SEC.곱셈, "응용", (rng) =>
    // x+y 를 한 문자로 묶는다.
    attempt<Gen>(80, () => {
      const mode = pick(rng, [0, 1] as const);
      if (mode === 0) {
        const a = intBetween(rng, 1, 8);
        const src = `${par(
          polyTex([
            [1, "x"],
            [1, "y"],
            [-a, ""],
          ]),
        )}${par(
          polyTex([
            [1, "x"],
            [1, "y"],
            [a, ""],
          ]),
        )}`;
        const out = polyTex([
          [1, "x^2"],
          [2, "xy"],
          [1, "y^2"],
          [-a * a, ""],
        ]);
        return {
          content: `${EXPAND}\n${M(src)}`,
          answer: M(out),
          solution: `${M("x+y=A")} 로 놓으면 ${M(
            `(A-${a})(A+${a})=A^2-${a * a}`,
          )} 이다.\n${M("A")} 에 ${M("x+y")} 를 대입하면 ${M(out)} 이다.`,
          facts: { mode, a },
        };
      }
      const a = nonZero(rng, -6, 6);
      const b = nonZero(rng, -6, 6);
      if (a === b) return null;
      const src = `${par(
        polyTex([
          [1, "x"],
          [1, "y"],
          [a, ""],
        ]),
      )}${par(
        polyTex([
          [1, "x"],
          [1, "y"],
          [b, ""],
        ]),
      )}`;
      const out = polyTex([
        [1, "x^2"],
        [2, "xy"],
        [1, "y^2"],
        [a + b, "x"],
        [a + b, "y"],
        [a * b, ""],
      ]);
      return {
        content: `${EXPAND}\n${M(src)}`,
        answer: M(out),
        solution: `${M("x+y=A")} 로 놓으면 ${M(
          `${par(lin(1, "A", a))}${par(lin(1, "A", b))}=${polyTex([
            [1, "A^2"],
            [a + b, "A"],
            [a * b, ""],
          ])}`,
        )} 이다.\n${M("A")} 에 ${M("x+y")} 를 대입해 정리하면 ${M(out)} 이다.`,
        facts: { mode, a, b },
      };
    }),
  )

def(
    MINOR_MUL,
    "13",
    "곱셈 공식을 이용한 분모의 유리화",
    SEC.곱셈,
    "심화하",
    (rng) =>
      attempt<Gen>(120, () => {
        const mode = pick(rng, [0, 1] as const);
        if (mode === 0) {
          const a = pick(rng, RADICANDS);
          const b = pick(rng, RADICANDS);
          if (a <= b) return null;
          const k = intBetween(rng, 1, 6);
          const den0 = a - b;
          const g = gcd(k, den0);
          const c = k / g;
          const den = den0 / g;
          const num = polyTex([
            [c, `\\sqrt{${a}}`],
            [c, `\\sqrt{${b}}`],
          ]);
          const out = den === 1 ? num : `\\dfrac{${num}}{${den}}`;
          const src = `\\dfrac{${k}}{\\sqrt{${a}}-\\sqrt{${b}}}`;
          const raw = `\\dfrac{${k}(\\sqrt{${a}}+\\sqrt{${b}})}{${den0}}`;
          return {
            content: `다음 수의 분모를 유리화하시오.\n${M(src)}`,
            answer: M(out),
            solution: `분모의 켤레는 ${M(
              `\\sqrt{${a}}+\\sqrt{${b}}`,
            )} 이다. 분모와 분자에 이것을 곱한다.\n분모가 ${M(
              `(\\sqrt{${a}}-\\sqrt{${b}})(\\sqrt{${a}}+\\sqrt{${b}})=${a}-${b}=${den0}`,
            )} 이므로 ${M(`${src}=${raw}=${out}`)} 이다.`,
            facts: { mode, a, b, k, den },
          };
        }
        const a = pick(rng, RADICANDS);
        const n = intBetween(rng, 1, 6);
        const k = intBetween(rng, 1, 6);
        let den0 = n * n - a;
        if (den0 === 0) return null;
        let p = k * n;
        let q = -k;
        if (den0 < 0) {
          den0 = -den0;
          p = -p;
          q = -q;
        }
        const g = gcd(gcd(Math.abs(p), Math.abs(q)), den0);
        // 유리수 항이 음수면 근호 항을 앞에 쓴다 — 「-3+루트21」 은 읽기 나쁘다.
        const num =
          p < 0
            ? polyTex([
                [q / g, `\\sqrt{${a}}`],
                [p / g, ""],
              ])
            : polyTex([
                [p / g, ""],
                [q / g, `\\sqrt{${a}}`],
              ]);
        const den = den0 / g;
        const out = den === 1 ? num : `\\dfrac{${num}}{${den}}`;
        const src = `\\dfrac{${k}}{${n}+\\sqrt{${a}}}`;
        const raw = `\\dfrac{${k}(${n}-\\sqrt{${a}})}{${n * n - a}}`;
        return {
          content: `다음 수의 분모를 유리화하시오.\n${M(src)}`,
          answer: M(out),
          solution: `분모의 켤레는 ${M(
            `${n}-\\sqrt{${a}}`,
          )} 이다. 분모와 분자에 이것을 곱한다.\n분모가 ${M(
            `(${n}+\\sqrt{${a}})(${n}-\\sqrt{${a}})=${n * n}-${a}=${n * n - a}`,
          )} 이므로 ${M(`${src}=${raw}=${out}`)} 이다.`,
          facts: { mode, a, n, k, den },
        };
      }),
  )

def(
    MINOR_MUL,
    "14",
    "의 꼴이 주어질 때 식의 값 구하기",
    SEC.곱셈,
    "심화하",
    (rng) => {
      // x=a±√b 이면 (x-a)^2=b — 발문의 식을 (x-a)^2 꼴로 몰아서 값을 낸다.
      const a = intBetween(rng, 1, 6);
      const b = pick(rng, RADICANDS);
      const s = pick(rng, [1, -1] as const);
      const c = nonZero(rng, -9, 9);
      const value = b - a * a + c;
      const expr = polyTex([
        [1, "x^2"],
        [-2 * a, "x"],
        [c, ""],
      ]);
      const xTex = polyTex([
        [a, ""],
        [s, `\\sqrt{${b}}`],
      ]);
      return {
        content: `${M(`x=${xTex}`)} 일 때, ${M(expr)} 의 값을 구하시오.`,
        answer: M(String(value)),
        solution: `${M(`x-${a}=${termTex(s, `\\sqrt{${b}}`, true)}`)} 이므로 양변을 제곱하면 ${M(
          `(x-${a})^2=${b}`,
        )} 이다.\n즉 ${M(
          `x^2-${2 * a}x=${b - a * a}`,
        )} 이므로 구하는 값은 ${M(`${b - a * a}${termTex(c, "", false)}=${value}`)} 이다.`,
        facts: { a, b, s, c, value },
      };
    },
  )

def(
    MINOR_FAC,
    "02",
    "공통인 인수로 묶어 인수분해하기",
    SEC.인수,
    "기본",
    (rng) =>
      attempt<Gen>(120, () => {
        const mode = pick(rng, [0, 1] as const);
        const k = intBetween(rng, 2, 6);
        if (mode === 0) {
          const p = intBetween(rng, 1, 2);
          const q = intBetween(rng, 0, 1);
          const a = intBetween(rng, 1, 5);
          const b = nonZero(rng, -5, 5);
          if (gcd(a, Math.abs(b)) !== 1) return null;
          const xs = p === 1 ? "x" : `x^${p}`;
          const ys = q === 1 ? "y" : "";
          const common = `${k}${xs}${ys}`;
          const inner = lin2(a, "x", b, "y");
          const t1 = k * a;
          const t2 = k * b;
          const src = polyTex([
            [t1, p + 1 === 1 ? `x${ys}` : `x^${p + 1}${ys}`],
            [t2, q + 1 === 1 ? `${xs}y` : `${xs}y^${q + 1}`],
          ]);
          return {
            content: `${FACTOR}\n${M(src)}`,
            answer: M(`${common}${par(inner)}`),
            solution: `두 항의 공통인 인수는 ${M(common)} 이다.\n${M(
              `${src}=${common}${par(inner)}`,
            )}`,
            facts: { mode, k, p, q, a, b },
          };
        }
        const a = intBetween(rng, 1, 5);
        const b = nonZero(rng, -5, 5);
        const c = nonZero(rng, -6, 6);
        if (gcd(gcd(a, Math.abs(b)), Math.abs(c)) !== 1) return null;
        const common = `${k}x`;
        const inner = polyTex([
          [a, "x"],
          [b, "y"],
          [c, ""],
        ]);
        const src = polyTex([
          [k * a, "x^2"],
          [k * b, "xy"],
          [k * c, "x"],
        ]);
        return {
          content: `${FACTOR}\n${M(src)}`,
          answer: M(`${common}${par(inner)}`),
          solution: `세 항의 공통인 인수는 ${M(common)} 이다.\n${M(
            `${src}=${common}${par(inner)}`,
          )}`,
          facts: { mode, k, a, b, c },
        };
      }),
  )

def(MINOR_FAC, "03", "의 인수분해", SEC.인수, "기본", (rng) =>
    attempt<Gen>(80, () => {
      const mode = pick(rng, [0, 1] as const);
      if (mode === 0) {
        const a = intBetween(rng, 2, 6);
        const b = nonZero(rng, -6, 6);
        if (gcd(a, Math.abs(b)) !== 1) return null;
        const src = polyTex([
          [a * a, "x^2"],
          [2 * a * b, "xy"],
          [b * b, "y^2"],
        ]);
        const out = `${par(lin2(a, "x", b, "y"))}^2`;
        return {
          content: `${FACTOR}\n${M(src)}`,
          answer: M(out),
          solution: `${M(`A=${termTex(a, "x", true)}`)}, ${M(
            `B=${termTex(Math.abs(b), "y", true)}`,
          )} 로 두면 ${M(`A^2=${termTex(a * a, "x^2", true)}`)}, ${M(
            `B^2=${termTex(b * b, "y^2", true)}`,
          )}, ${M(
            `2AB=${termTex(2 * a * Math.abs(b), "xy", true)}`,
          )} 이므로 완전제곱식이다.\n${M(`${src}=${out}`)}`,
          facts: { mode, a, b },
        };
      }
      const k = intBetween(rng, 1, 4);
      const m = nonZero(rng, -8, 8);
      const src = polyTex([
        [k, "x^2"],
        [2 * k * m, "x"],
        [k * m * m, ""],
      ]);
      const monic = polyTex([
        [1, "x^2"],
        [2 * m, "x"],
        [m * m, ""],
      ]);
      const inner = `${par(lin(1, "x", m))}^2`;
      const out = k === 1 ? inner : `${k}${inner}`;
      return {
        content: `${FACTOR}\n${M(src)}`,
        answer: M(out),
        solution: `${
          k === 1
            ? ""
            : `공통인 인수 ${M(String(k))}${eulReul(
                k,
              )} 먼저 묶어 내면 ${M(`${k}${par(monic)}`)} 이다.\n`
        }상수항이 ${M(`${wp(m, "")}^2=${m * m}`)} 이고 ${M(
          "x",
        )} 의 계수가 ${M(`2\\times${wp(m, "")}=${2 * m}`)} 이므로 완전제곱식이다.\n${M(
          `${src}=${out}`,
        )}`,
        facts: { mode, k, m },
      };
    }),
  )

def(
    MINOR_FAC,
    "04",
    "완전제곱식이 되도록 하는 미지수의 값 구하기",
    SEC.인수,
    "응용",
    (rng) =>
      attempt<Gen>(80, () => {
        const mode = pick(rng, [0, 1, 2] as const);
        if (mode === 0) {
          const m = nonZero(rng, -9, 9);
          const src = polyTex([
            [1, "x^2"],
            [2 * m, "x"],
          ]);
          return {
            content: `${M(`${src}+k`)} 가 완전제곱식이 되도록 하는 상수 ${M(
              "k",
            )} 의 값을 구하시오.`,
            answer: M(String(m * m)),
            solution: `${M("x")} 의 계수의 절반의 제곱이 상수항이어야 한다.\n${M(
              `k=\\left(\\dfrac{${2 * m}}{2}\\right)^2=${m * m}`,
            )} 이다.`,
            facts: { mode, m, value: m * m },
          };
        }
        if (mode === 1) {
          const m = intBetween(rng, 2, 9);
          return {
            content: `${M(`x^2+ax+${m * m}`)}${iGa(
              m * m,
            )} 완전제곱식이 되도록 하는 상수 ${M(
              "a",
            )} 의 값을 구하시오. (단, ${M("a>0")})`,
            answer: M(String(2 * m)),
            solution: `상수항이 ${M(`${m * m}=${m}^2`)} 이므로 ${M(
              `(x+${m})^2`,
            )} 의 꼴이어야 한다.\n따라서 ${M(`a=2\\times${m}=${2 * m}`)} 이다.`,
            facts: { mode, m, value: 2 * m },
          };
        }
        const p = nonZero(rng, -9, 9);
        const q = nonZero(rng, -9, 9);
        if ((p + q) % 2 !== 0) return null;
        if (p === q) return null;
        const value = ((p - q) / 2) ** 2;
        return {
          content: `${M(
            `${par(lin(1, "x", p))}${par(lin(1, "x", q))}+k`,
          )} 가 완전제곱식이 되도록 하는 상수 ${M("k")} 의 값을 구하시오.`,
          answer: M(String(value)),
          solution: `${M(
            `${par(lin(1, "x", p))}${par(lin(1, "x", q))}=${polyTex([
              [1, "x^2"],
              [p + q, "x"],
              [p * q, ""],
            ])}`,
          )} 이다.\n${M("x")} 의 계수의 절반의 제곱에서 상수항을 빼면 ${M(
            `k=\\left(\\dfrac{${p + q}}{2}\\right)^2-${wp(p * q, "")}=${value}`,
          )} 이다.`,
          facts: { mode, p, q, value },
        };
      }),
  )

def(
    MINOR_FAC,
    "05",
    "근호 안이 완전제곱식으로 인수분해되는 식",
    SEC.인수,
    "심화하",
    (rng) =>
      attempt<Gen>(80, () => {
        const mode = pick(rng, [0, 1] as const);
        const lo = intBetween(rng, -4, 4);
        const gap = intBetween(rng, 2, 7);
        const hi = lo + gap;
        const sq = (m: number): string =>
          `\\sqrt{${polyTex([
            [1, "x^2"],
            [-2 * m, "x"],
            [m * m, ""],
          ])}}`;
        // lo<x<hi 이므로 √((x-lo)^2)=x-lo, √((x-hi)^2)=hi-x 다.
        const src = mode === 0 ? `${sq(lo)}+${sq(hi)}` : `${sq(lo)}-${sq(hi)}`;
        const out =
          mode === 0
            ? String(hi - lo)
            : polyTex([
                [2, "x"],
                [-(lo + hi), ""],
              ]);
        return {
          content: `${M(`${lo}<x<${hi}`)} 일 때, 다음 식을 간단히 하시오.\n${M(
            src,
          )}`,
          answer: M(out),
          solution: `${M(`${lin(1, "x", -lo)}>0`)} 이므로 ${M(
            `${sq(lo)}=${lin(1, "x", -lo)}`,
          )} 이고, ${M(`${lin(1, "x", -hi)}<0`)} 이므로 ${M(
            `${sq(hi)}=${lin(-1, "x", hi)}`,
          )} 이다.\n두 식을 ${mode === 0 ? "더하면" : "빼면"} ${M(out)} 이다.`,
          facts: { mode, lo, hi },
        };
      }),
  )

def(MINOR_FAC, "08", "의 인수분해", SEC.인수, "응용", (rng) =>
    attempt<Gen>(120, () => {
      const a = intBetween(rng, 1, 5);
      const b = nonZero(rng, -7, 7);
      const c = intBetween(rng, 1, 5);
      const d = nonZero(rng, -7, 7);
      if (a * c < 2) return null;
      if (gcd(a, Math.abs(b)) !== 1 || gcd(c, Math.abs(d)) !== 1) return null;
      if (a === c && b === d) return null;
      const [f1, f2] =
        a < c || (a === c && b < d)
          ? [lin(a, "x", b), lin(c, "x", d)]
          : [lin(c, "x", d), lin(a, "x", b)];
      const src = polyTex([
        [a * c, "x^2"],
        [a * d + b * c, "x"],
        [b * d, ""],
      ]);
      const out = `${par(f1)}${par(f2)}`;
      return {
        content: `${FACTOR}\n${M(src)}`,
        answer: M(out),
        solution: `${M(
          "acx^2+(ad+bc)x+bd=(ax+b)(cx+d)",
        )} 에서 ${M(`ac=${a * c}`)}, ${M(`bd=${b * d}`)} 를 만족하는 짝을 찾는다.\n${M(
          `${src}=${out}`,
        )}`,
        facts: { a, b, c, d },
      };
    }),
  )

def(MINOR_FAC, "09", "인수분해 공식 종합", SEC.인수, "응용", (rng) =>
    // 공통인수를 먼저 묶고 그 안을 다시 인수분해한다 — 두 단계를 한 문항에서 쓴다.
    attempt<Gen>(120, () => {
      const k = intBetween(rng, 2, 5);
      const a = intBetween(rng, 1, 4);
      const b = nonZero(rng, -6, 6);
      const c = intBetween(rng, 1, 4);
      const d = nonZero(rng, -6, 6);
      if (gcd(a, Math.abs(b)) !== 1 || gcd(c, Math.abs(d)) !== 1) return null;
      if (a === c && b === d) return null;
      const [f1, f2] =
        a < c || (a === c && b < d)
          ? [lin(a, "x", b), lin(c, "x", d)]
          : [lin(c, "x", d), lin(a, "x", b)];
      const inner = polyTex([
        [a * c, "x^2"],
        [a * d + b * c, "x"],
        [b * d, ""],
      ]);
      const src = polyTex([
        [k * a * c, "x^2"],
        [k * (a * d + b * c), "x"],
        [k * b * d, ""],
      ]);
      const out = `${k}${par(f1)}${par(f2)}`;
      return {
        content: `${FACTOR}\n${M(src)}`,
        answer: M(out),
        solution: `세 항의 공통인 인수 ${M(String(k))}${eulReul(
          k,
        )} 먼저 묶어 내면 ${M(
          `${k}${par(inner)}`,
        )} 이다.\n괄호 안을 다시 인수분해하면 ${M(`${src}=${out}`)} 이다.`,
        facts: { k, a, b, c, d },
      };
    }),
  )

def(
    MINOR_FAC,
    "10",
    "두 다항식의 공통인 인수 구하기",
    SEC.응용,
    "응용",
    (rng) =>
      attempt<Gen>(120, () => {
        // 공통인수 (x+n) 을 먼저 정하고 두 이차식을 그 배수로 짓는다.
        const n = nonZero(rng, -6, 6);
        const m = nonZero(rng, -8, 8);
        const a = intBetween(rng, 1, 4);
        const b = nonZero(rng, -8, 8);
        if (m === n) return null;
        if (gcd(a, Math.abs(b)) !== 1) return null;
        if (a === 1 && b === m) return null;
        if (a === 1 && b === n) return null;
        // 공통인수가 **하나로 정해져야** 한다: `b === a*n` 이면 둘째 식이
        // `a(x+n)^2`, `b === a*m` 이면 `a(x+m)(x+n)` 이라 인수가 둘이 겹친다.
        if (b === a * n || b === a * m) return null;
        const p1 = polyTex([
          [1, "x^2"],
          [m + n, "x"],
          [m * n, ""],
        ]);
        const p2 = polyTex([
          [a, "x^2"],
          [a * n + b, "x"],
          [b * n, ""],
        ]);
        const common = lin(1, "x", n);
        return {
          content: `다음 두 다항식의 공통인 인수를 구하시오.\n${M(p1)}, ${M(
            p2,
          )}`,
          answer: M(common),
          solution: `${M(`${p1}=${par(lin(1, "x", m))}${par(common)}`)} 이다.\n${M(
            `${p2}=${par(lin(a, "x", b))}${par(common)}`,
          )} 이므로 공통인 인수는 ${M(common)} 이다.`,
          facts: { n, m, a, b },
        };
      }),
  )

def(MINOR_FAC, "13", "인수분해의 도형에의 활용 ⑴", SEC.응용, "응용", (rng) =>
    attempt<Gen>(80, () => {
      // 넓이가 x^2·x·1 인 조각을 붙여 만든 직사각형 — 그림 대신 개수를 글로 준다.
      const p = intBetween(rng, 1, 6);
      const q = intBetween(rng, 1, 6);
      const b = p + q;
      const c = p * q;
      const peri = polyTex([
        [4, "x"],
        [2 * b, ""],
      ]);
      return {
        content: `넓이가 ${M("x^2")} 인 정사각형 ${M(
          "1",
        )} 개, 넓이가 ${M("x")} 인 직사각형 ${M(
          String(b),
        )} 개, 넓이가 ${M("1")} 인 정사각형 ${M(
          String(c),
        )} 개를 빈틈없이 겹치지 않게 모두 붙여 하나의 큰 직사각형을 만들었다. 이 직사각형의 둘레의 길이를 구하시오.`,
        answer: M(peri),
        solution: `조각의 넓이의 합은 ${M(
          polyTex([
            [1, "x^2"],
            [b, "x"],
            [c, ""],
          ]),
        )} 이고, 인수분해하면 ${M(
          `${par(lin(1, "x", p))}${par(lin(1, "x", q))}`,
        )} 이다.\n큰 직사각형의 가로·세로의 길이가 ${M(
          lin(1, "x", p),
        )}, ${M(lin(1, "x", q))} 이므로 둘레의 길이는 ${M(
          `2\\times(${lin(1, "x", p)}+${lin(1, "x", q)})=${peri}`,
        )} 이다.`,
        facts: { p, q, b, c },
      };
    }),
  )

def(MINOR_FAC, "14", "인수분해의 도형에의 활용 ⑵", SEC.응용, "응용", (rng) =>
    attempt<Gen>(120, () => {
      const a = intBetween(rng, 1, 4);
      // 두 변이 모두 «길이» 이므로 상수항을 양수로 둔다 — `2x-5` 를 가로라고
      // 하면 작은 `x` 에서 음수가 된다.
      const b = intBetween(rng, 1, 6);
      const c = intBetween(rng, 1, 4);
      const d = intBetween(rng, 1, 6);
      if (gcd(a, b) !== 1 || gcd(c, d) !== 1) return null;
      if (a * c < 2) return null;
      const area = polyTex([
        [a * c, "x^2"],
        [a * d + b * c, "x"],
        [b * d, ""],
      ]);
      const given = lin(c, "x", d);
      const other = lin(a, "x", b);
      return {
        content: `세로의 길이가 ${M(given)} 인 직사각형의 넓이가 ${M(
          area,
        )} 일 때, 이 직사각형의 가로의 길이를 구하시오.`,
        answer: M(other),
        solution: `넓이를 인수분해하면 ${M(
          `${area}=${par(other)}${par(given)}`,
        )} 이다.\n세로의 길이가 ${M(given)} 이므로 가로의 길이는 ${M(
          other,
        )} 이다.`,
        facts: { a, b, c, d },
      };
    }),
  )

def(
    MINOR_FAC,
    "19",
    "인수분해 공식을 이용한 수의 계산",
    SEC.응용,
    "응용",
    (rng) => {
      const mode = pick(rng, [0, 1, 2] as const);
      if (mode === 0) {
        const s = intBetween(rng, 3, 9) * 10;
        // ⚠️ `t < s` 여야 한다 — 아니면 `b` 가 음수가 되어 지면에 `85^2--5^2` 가
        //    나가고, 그것은 `85^2+5^2` 로 읽힌다(2026-08-24 시험이 잡았다).
        const t = attempt<number>(60, () => {
          const v = intBetween(rng, 1, 9) * 5;
          return v < s ? v : null;
        });
        const a = s + t;
        const b = s - t;
        const value = a * a - b * b;
        return {
          content: `인수분해 공식을 이용하여 다음을 계산하시오.\n${M(
            `${a}^2-${b}^2`,
          )}`,
          answer: M(String(value)),
          solution: `${M("a^2-b^2=(a+b)(a-b)")} 임을 이용한다.\n${M(
            `(${a}+${b})(${a}-${b})=${a + b}\\times${a - b}=${value}`,
          )}`,
          facts: { mode, a, b, value },
        };
      }
      if (mode === 1) {
        const base = pick(rng, [100, 1000] as const);
        const t = intBetween(rng, 1, 9);
        const a = base - t;
        const value = (a + t) * (a + t);
        return {
          content: `인수분해 공식을 이용하여 다음을 계산하시오.\n${M(
            `${a}^2+2\\times${a}\\times${t}+${t}^2`,
          )}`,
          answer: M(String(value)),
          solution: `${M("a^2+2ab+b^2=(a+b)^2")} 임을 이용한다.\n${M(
            `(${a}+${t})^2=${base}^2=${value}`,
          )}`,
          facts: { mode, a, t, value },
        };
      }
      const s = intBetween(rng, 3, 9) * 10;
      const t = intBetween(rng, 1, 8);
      const a = s + t;
      const b = s - t;
      const value = a + b;
      return {
        content: `인수분해 공식을 이용하여 다음을 계산하시오.\n${M(
          `\\dfrac{${a}^2-${b}^2}{${a - b}}`,
        )}`,
        answer: M(String(value)),
        solution: `분자를 인수분해하면 ${M(
          `${a}^2-${b}^2=(${a}+${b})(${a}-${b})`,
        )} 이다.\n${M(
          `\\dfrac{(${a}+${b})\\times${a - b}}{${a - b}}=${value}`,
        )}`,
        facts: { mode, a, b, value },
      };
    },
  )
